//! Intl.DateTimeFormat's non-gregorian calendars (the ones node 22.23.5's ICU supports): their
//! arithmetic, the -u-ca- / calendar option, and the fields their patterns format. Per-locale names and
//! patterns are in calendar_data.rs, generated by scripts/intl-cal from node's ICU.
//!
//! Patterns extend the gregorian ones with r (related gregorian year), U (cyclic year name) and a mark
//! (U+E001..U+E004) before a numeric field for the numbering ICU's pattern overrides it with: Hebrew
//! letters, Han digits, Chinese day names, Japanese 元 for an era's first year.

use super::calendar_data::{CAL_LOCALES, CAL_PATTERNS, CAL_ROWS, CHINESE, DANGI, HIJRI};
use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;

pub(super) struct CalLocale {
    pub(super) cal: u8,
    /// The first tag of the DateLocale it goes with, or "en" for the built-in English.
    pub(super) key: &'static str,
    /// Month names by month code: format long, short, narrow, then standalone long, short, narrow.
    pub(super) months: [&'static [&'static str]; 6],
    /// Era names long, short, narrow.
    pub(super) eras: [&'static [&'static str]; 3],
    /// A lunisolar leap month's number, around {0}.
    pub(super) leap: &'static str,
    /// The 60 cyclic year names.
    pub(super) years: &'static [&'static str],
    pub(super) date: [u16; 54],
    pub(super) datez: [u16; 54],
    pub(super) styles: [u16; 4],
    pub(super) glue: [&'static str; 4],
    pub(super) style_glue: [&'static str; 4],
    /// Time patterns, for the few calendar locales whose times differ from the gregorian locale's.
    pub(super) time: Option<&'static TimeTable>,
}

/// Times by date.rs's time key (DateLocale's time and timez), and timeStyle patterns by hour cycle.
pub(super) struct TimeTable {
    pub(super) time: [u16; 189],
    pub(super) timez: [u16; 189],
    pub(super) styles: [[u16; 4]; 7],
}

/// The calendar locale's own time pattern, if its times differ from the gregorian locale's: by
/// timeStyle index, else by date.rs's time fields (f[5..9]), fractional digits and cycle key; zone: a
/// timeZoneName was asked for (the pattern's z letters stand for its short name).
pub(super) fn time(l: &CalLocale, f: &[usize; 10], fsd: usize, cy: usize, ts: Option<usize>, zone: bool) -> Option<&'static str> {
    let t = l.time?;
    if let Some(i) = ts {
        return pattern(t.styles[cy][i]);
    }
    let tk = ((((f[6] * 3 + f[7]) * 3 + f[8]) * 7 + cy) * 4 + f[5]) * 4 + fsd;
    let rows = if zone { &t.timez } else { &t.time };
    pattern(CAL_ROWS[usize::from(rows[tk >> 4])][tk & 15])
}

/// Calendar identifiers, gregory first; the index is CalLocale::cal.
pub(super) const CALENDARS: [&str; 18] = [
    "gregory", "buddhist", "roc", "japanese", "persian", "islamic-civil", "islamic-tbla", "islamic-umalqura", "islamic", "islamic-rgsa", "hebrew", "indian", "coptic",
    "ethiopic", "ethioaa", "chinese", "dangi", "iso8601",
];

/// The supported calendar a -u-ca- value or calendar option names, after aliases.
pub(super) fn canonical(v: &str) -> Option<usize> {
    let v = v.to_ascii_lowercase();
    let v = match v.as_str() {
        "islamicc" => "islamic-civil",
        "ethiopic-amete-alem" => "ethioaa",
        o => o,
    };
    CALENDARS.iter().position(|c| *c == v)
}

/// A calendar option's shape: one or more 3-8 alphanumeric subtags.
pub(super) fn well_formed(v: &str) -> bool {
    !v.is_empty() && v.split('-').all(|p| (3..=8).contains(&p.len()) && p.bytes().all(|b| b.is_ascii_alphanumeric()))
}

/// The calendar locale for calendar cal with the DateLocale whose first tag is key.
pub(super) fn locale_for(cal: usize, key: &str) -> Option<usize> {
    CAL_LOCALES.iter().position(|l| usize::from(l.cal) == cal && l.key == key)
}

pub(super) fn get(i: usize) -> &'static CalLocale {
    &CAL_LOCALES[i]
}

fn pattern(i: u16) -> Option<&'static str> {
    (i != u16::MAX).then(|| CAL_PATTERNS[usize::from(i)])
}

fn date_cell(rows: &[u16; 54], k: usize) -> Option<&'static str> {
    pattern(CAL_ROWS[usize::from(rows[k >> 4])][k & 15])
}

fn join(glue: &str, d: &str, t: &str) -> String {
    glue.replacen("{1}", d, 1).replacen("{0}", t, 1)
}

/// The pattern for a calendar locale: its own date part, glued to the time part (time, the locale's
/// gregorian pattern for the same options without date fields: times don't change with the calendar).
/// f and the dateStyle index are as date.rs's resolve has them; zone: a timeZoneName was asked for.
pub(super) fn compose(l: &CalLocale, f: &[usize; 10], ds: Option<usize>, time: &str, zone: bool) -> String {
    if let Some(d) = ds {
        let dp = pattern(l.styles[d]).unwrap_or("");
        return if time.is_empty() { dp.to_string() } else { join(l.style_glue[d], dp, time) };
    }
    let dk = (((f[0] * 4 + f[1]) * 3 + f[2]) * 6 + f[3]) * 3 + f[4];
    if time.is_empty() {
        return date_cell(if zone { &l.datez } else { &l.date }, dk).unwrap_or("").to_string();
    }
    if dk == 0 {
        return time.to_string();
    }
    let only_era = f[1] != 0 && f[0] == 0 && f[2] == 0 && f[3] == 0 && f[4] == 0;
    let d = if only_era { ["", "GGGG", "G", "GGGGG"][f[1]] } else { date_cell(&l.date, dk).unwrap_or("") };
    let g = match f[3] {
        3 if f[0] != 0 => l.glue[0],
        3 => l.glue[1],
        4 => l.glue[2],
        _ => l.glue[3],
    };
    join(g, d, time)
}

/// A calendar date: era index, year in era, month code (as scripts/intl-cal/cal.js numbers them), day,
/// and for lunisolar calendars the related gregorian year and 60-year cycle position.
#[derive(Clone, Copy, Default)]
pub(super) struct Fields {
    era: i64,
    year: i64,
    month: usize,
    day: i64,
    ry: i64,
    cyc: usize,
    leap: bool,
}

const JD_EPOCH: i64 = 2_440_588;
const JA_ERAS: [(i64, u32, u32); 5] = [(1868, 9, 8), (1912, 7, 30), (1926, 12, 25), (1989, 1, 8), (2019, 5, 1)];

fn from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let mp = i64::from((m + 9) % 12);
    let doy = (153 * mp + 2) / 5 + i64::from(d) - 1;
    era * 146_097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719_468
}

fn leap_g(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn ceil_div(a: i64, b: i64) -> i64 {
    -((-a).div_euclid(b))
}

fn islamic_tab(days: i64, epoch: i64) -> Fields {
    let jd = days + JD_EPOCH;
    let year = (30 * (jd - epoch) + 10646).div_euclid(10631);
    let ystart = epoch + 354 * (year - 1) + (3 + 11 * year).div_euclid(30);
    let month = ceil_div(2 * (jd - 29 - ystart), 59).clamp(0, 11);
    let mstart = ystart + ceil_div(59 * month, 2);
    Fields { year, month: month as usize, day: jd - mstart + 1, ..Fields::default() }
}

fn persian(days: i64) -> Fields {
    let dse = days + JD_EPOCH - 1_948_320;
    let year = 1 + (33 * dse + 3).div_euclid(12053);
    let doy = dse - (365 * (year - 1) + (8 * year + 21).div_euclid(33));
    let month = if doy < 216 { doy / 31 } else { (doy - 6) / 30 };
    let day = doy - if month < 7 { month * 31 } else { month * 30 + 6 } + 1;
    Fields { year, month: month as usize, day, ..Fields::default() }
}

fn indian(days: i64, gy: i64) -> Fields {
    let start = |y: i64| from_civil(y + 78, 3, if leap_g(y + 78) { 21 } else { 22 });
    let mut year = gy - 78;
    let mut yday = days - start(year);
    if yday < 0 {
        year -= 1;
        yday = days - start(year);
    }
    let l1 = if leap_g(year + 78) { 31 } else { 30 };
    let (month, day) = if yday < l1 {
        (0, yday + 1)
    } else {
        let md = yday - l1;
        if md < 155 { (1 + md / 31, md % 31 + 1) } else { (6 + (md - 155) / 30, (md - 155) % 30 + 1) }
    };
    Fields { year, month: month as usize, day, ..Fields::default() }
}

fn coptic(days: i64, epoch: i64, off: i64) -> Fields {
    let x = days + JD_EPOCH - epoch;
    let c4 = x.div_euclid(1461);
    let r4 = x - c4 * 1461;
    let year = 4 * c4 + r4 / 365 - r4 / 1460;
    let doy = if r4 == 1460 { 365 } else { r4 % 365 };
    Fields { year: year + off, month: (doy / 30) as usize, day: doy % 30 + 1, ..Fields::default() }
}

const HOUR_PARTS: i64 = 1080;
const DAY_PARTS: i64 = 24 * HOUR_PARTS;

fn hleap(y: i64) -> bool {
    (12 * y + 17).rem_euclid(19) >= 12
}

/// Days from the Hebrew epoch to 1 Tishri of year y, with ICU's postponements.
fn hstart(y: i64) -> i64 {
    let months = (235 * y - 234).div_euclid(19);
    let frac = months * (12 * HOUR_PARTS + 793) + 11 * HOUR_PARTS + 204;
    let mut day = months * 29 + frac.div_euclid(DAY_PARTS);
    let parts = frac.rem_euclid(DAY_PARTS);
    let wd = day.rem_euclid(7);
    if wd == 2 || wd == 4 || wd == 6 {
        day += 1;
    }
    if wd == 1 && parts > 15 * HOUR_PARTS + 204 && !hleap(y) {
        day += 2;
    } else if wd == 0 && parts > 21 * HOUR_PARTS + 589 && hleap(y - 1) {
        day += 1;
    }
    day
}

fn hebrew(days: i64) -> Fields {
    let d = days + JD_EPOCH - 347_998;
    let mut y = (19 * d).div_euclid(6940) + 1;
    while hstart(y) > d {
        y -= 1;
    }
    while hstart(y + 1) <= d {
        y += 1;
    }
    let ty = (hstart(y + 1) - hstart(y)) % 10 - 3;
    let leap = hleap(y);
    let ml = [30, if ty == 2 { 30 } else { 29 }, if ty == 0 { 29 } else { 30 }, 29, 30, if leap { 30 } else { 0 }, 29, 30, 29, 30, 29, 30, 29];
    let mut r = d - hstart(y);
    let mut m = 0;
    while m < 12 && r >= ml[m] {
        r -= ml[m];
        m += 1;
    }
    Fields { year: y, month: if m == 6 && leap { 13 } else { m }, day: r + 1, leap, ..Fields::default() }
}

/// Walks the months of a year from its first day, a set bit of mask marking a 30-day month.
fn month_of(mut r: i64, mask: u16, last: usize) -> (usize, i64) {
    let mut m = 0;
    while m < last && r >= if mask >> m & 1 == 1 { 30 } else { 29 } {
        r -= if mask >> m & 1 == 1 { 30 } else { 29 };
        m += 1;
    }
    (m, r + 1)
}

fn lunisolar(tab: &[(i32, u16, u8, i16)], days: i64) -> Fields {
    let (ny, mask, lp, ry) = tab[tab.partition_point(|e| i64::from(e.0) <= days).saturating_sub(1)];
    let (lp, ry) = (usize::from(lp), i64::from(ry));
    let (m, day) = month_of(days - i64::from(ny), mask, 12);
    let (month, leap) = if lp != 0 && m == lp { (11 + lp, true) } else if lp != 0 && m > lp { (m - 1, false) } else { (m, false) };
    let cyc = ((ry - 4).rem_euclid(60) + 1) as usize;
    Fields { era: (ry + 2636).div_euclid(60) + 1, year: cyc as i64, month, day, ry, cyc, leap }
}

fn hijri(tab: &[(i16, i32, u16)], days: i64) -> Fields {
    let (first, last) = (tab[0], tab[tab.len() - 1]);
    if days < i64::from(first.1) || days >= i64::from(last.1) + 354 {
        return islamic_tab(days, 1_948_440);
    }
    let (y, start, mask) = tab[tab.partition_point(|e| i64::from(e.1) <= days).saturating_sub(1)];
    let (month, day) = month_of(days - i64::from(start), mask, 11);
    Fields { year: i64::from(y), month, day, ..Fields::default() }
}

/// The calendar date of local day number days (since 1970-01-01), whose gregorian date is (y, m, d).
pub(super) fn fields(cal: usize, days: i64, (y, m, d): (i64, u32, u32)) -> Fields {
    let g = |era: i64, year: i64| Fields { era, year, month: (m - 1) as usize, day: i64::from(d), ..Fields::default() };
    match CALENDARS[cal] {
        "buddhist" => g(0, y + 543),
        "roc" => if y > 1911 { g(1, y - 1911) } else { g(0, 1912 - y) },
        "japanese" => {
            let e = JA_ERAS.iter().rposition(|&(a, b, c)| days >= from_civil(a, b, c)).unwrap_or(0);
            g(e as i64, y - JA_ERAS[e].0 + 1)
        }
        "persian" => persian(days),
        "islamic-civil" => islamic_tab(days, 1_948_440),
        "islamic-tbla" => islamic_tab(days, 1_948_439),
        "islamic-umalqura" => hijri(HIJRI[0], days),
        "islamic" | "islamic-rgsa" => hijri(HIJRI[1], days),
        "hebrew" => hebrew(days),
        "indian" => indian(days, y),
        "coptic" => coptic(days, 1_824_665, 0),
        "ethiopic" => coptic(days, 1_723_856, 0),
        "ethioaa" => coptic(days, 1_723_856, 5500),
        "chinese" => lunisolar(CHINESE, days),
        "dangi" => lunisolar(DANGI, days),
        _ => if y > 0 { g(1, y) } else { g(0, 1 - y) },
    }
}

/// The numbering a pattern mark selects for the field after it.
pub(super) fn mark(c: char) -> Option<u8> {
    matches!(c, '\u{e001}'..='\u{e004}').then_some((c as u32 - 0xe000) as u8)
}

const HANI: [char; 10] = ['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九'];

/// ICU's %hebrew numbering for 1..999, with geresh and gershayim.
fn hebr(n: i64) -> String {
    const H: [&str; 10] = ["", "ק", "ר", "ש", "ת", "תק", "תר", "תש", "תת", "תתק"];
    const T: [&str; 10] = ["", "י", "כ", "ל", "מ", "נ", "ס", "ע", "פ", "צ"];
    const O: [&str; 10] = ["", "א", "ב", "ג", "ד", "ה", "ו", "ז", "ח", "ט"];
    let (h, t, o) = ((n / 100 % 10) as usize, (n / 10 % 10) as usize, (n % 10) as usize);
    let mut s = String::from(H[h]);
    if t == 1 && (o == 5 || o == 6) {
        s.push('ט');
        s.push(if o == 5 { 'ו' } else { 'ז' });
    } else if n % 100 == 44 && h == 7 {
        s.push_str("דמ");
    } else if n % 100 == 98 && h == 6 {
        s.push_str("חצ");
    } else {
        s.push_str(T[t]);
        s.push_str(O[o]);
    }
    let mut chars: Vec<char> = s.chars().collect();
    if chars.len() == 1 {
        chars.push('׳');
    } else if let Some(last) = chars.pop() {
        chars.push('״');
        chars.push(if last == 'פ' { 'ף' } else { last });
    }
    chars.into_iter().collect()
}

fn marked(m: u8, v: i64, year: bool) -> String {
    match m {
        1 => hebr(if year && v > 5000 && v < 6000 { v - 5000 } else { v }),
        2 => v.to_string().chars().map(|c| c.to_digit(10).map_or(c, |d| HANI[d as usize])).collect(),
        3 => match v as usize {
            d @ 1..=9 => format!("初{}", HANI[d]),
            10 => "初十".to_string(),
            d @ 11..=19 => format!("十{}", HANI[d - 10]),
            20 => "二十".to_string(),
            d @ 21..=29 => format!("廿{}", HANI[d - 20]),
            _ => "三十".to_string(),
        },
        _ => if v == 1 { "元".to_string() } else { v.to_string() },
    }
}

/// The part a calendar field letter formats to, or None for the letters calendars leave alone.
pub(super) fn field(l: &CalLocale, f: &Fields, c: char, n: usize, mk: Option<u8>) -> Option<(&'static str, String)> {
    let width = match n {
        4 => 0,
        5 => 2,
        _ => 1,
    };
    let cal = CALENDARS[usize::from(l.cal)];
    let luni = matches!(cal, "chinese" | "dangi");
    let num = |v: i64| if n >= 2 { format!("{:02}", v.rem_euclid(100)) } else { v.to_string() };
    Some(match c {
        'G' if luni => ("era", f.era.to_string()),
        'G' => ("era", l.eras[width].get(f.era as usize).copied().unwrap_or("").to_string()),
        'y' => (
            "year",
            match mk {
                Some(m) => marked(m, f.year, true),
                None => num(f.year).to_string(),
            },
        ),
        'r' => ("relatedYear", f.ry.to_string()),
        'U' => ("yearName", l.years.get(f.cyc.wrapping_sub(1)).copied().unwrap_or("").to_string()),
        'M' | 'L' if n <= 2 => {
            let mn = match cal {
                "hebrew" if f.leap => if f.month == 13 { 7 } else { f.month + 1 },
                "hebrew" => if f.month <= 5 { f.month + 1 } else { f.month },
                _ if luni && f.month >= 12 => f.month - 11,
                _ => f.month + 1,
            };
            let v = num(mn as i64);
            ("month", if luni && f.month >= 12 { l.leap.replacen("{0}", &v, 1) } else { v })
        }
        'M' | 'L' => ("month", l.months[usize::from(c == 'L') * 3 + width].get(f.month).copied().unwrap_or("").to_string()),
        'd' => (
            "day",
            match mk {
                Some(m) => marked(m, f.day, false),
                None => num(f.day),
            },
        ),
        _ => return None,
    })
}
